fx=json.load(open('fixtures/public_gnss_case.json'))

def rot_exact(sv, th):
    ct,st=np.cos(th),np.sin(th)
    return np.array([ct*sv[0]+st*sv[1], -st*sv[0]+ct*sv[1], sv[2]])
def rot_fo(sv, th):
    return np.array([sv[0]+th*sv[1], sv[1]-th*sv[0], sv[2]])

models = {}
def register(name, fn):
    models[name]=fn

def make(rotfn, iters, tau_from_pr=False):
    def f(sv, rx, b, pr):
        if tau_from_pr:
            tau=(pr-b)/C
            return np.linalg.norm(rotfn(sv, W*tau)-rx)
        tau=np.linalg.norm(sv-rx)/C
        for _ in range(iters):
